-- ==========================================================================================
-- 01_tables.sql  ·  Reference (REF), landing (RAW) and external signal (EXT) tables
-- RAW tables are shaped like the source systems on the architecture page: HL7 v2 / FHIR R4
-- messages as VARIANT, CDC copies of the HIS and SAP, payer responses as free text.
-- ==========================================================================================
USE ROLE LUZ_ADMIN;
USE WAREHOUSE LUZ_LOAD_WH;
USE DATABASE LUZSAUDE_DEMO;

-- ============================== REF: reference and master data ==============================
CREATE OR REPLACE TABLE REF.HOSPITALS (
  HOSPITAL_ID STRING PRIMARY KEY, NAME STRING, SHORT_NAME STRING, REGION STRING, BEDS INT,
  IS_FLAGSHIP BOOLEAN, IS_NEW BOOLEAN, HAS_DETAIL BOOLEAN,
  TARGET_OCC_PCT FLOAT, TARGET_ALOS_DAYS FLOAT, TARGET_ADMISSIONS_DAY INT, TARGET_DISCHARGES_DAY INT,
  TARGET_ER_VISITS_DAY INT, TARGET_ER_WAIT_MIN FLOAT, TARGET_OR_UTIL_PCT FLOAT, TARGET_OR_CANCEL_PCT FLOAT,
  TARGET_NPS FLOAT, TARGET_READM_PCT FLOAT, TARGET_IACS_PCT FLOAT, TARGET_COMPL_PCT FLOAT,
  TARGET_CONSULTS_MONTH INT, TARGET_DAYS_TO_FIRST FLOAT, TARGET_NOSHOW_PCT FLOAT, TARGET_TELE_PCT FLOAT,
  REVENUE_2025_MEUR FLOAT, MARGIN_PCT FLOAT, ABSENT_PCT FLOAT
) COMMENT = '15 hospitals of the group with the operating targets the synthetic facts are calibrated to';
CREATE OR REPLACE TABLE REF.NEW_UNITS (HOSPITAL_ID STRING, OPENED STRING, MONTHS_OPEN INT, CONSULT_PLAN_MONTH INT, STAFF_PLAN INT, STAFF_HIRED INT, BREAK_EVEN STRING);
CREATE OR REPLACE TABLE REF.CLINICS (CLINIC_ID STRING PRIMARY KEY, NAME STRING, SHORT_NAME STRING, REGION STRING, TARGET_CONSULTS_MONTH INT, TARGET_DAYS_TO_FIRST FLOAT, TARGET_NOSHOW_PCT FLOAT, TARGET_TELE_PCT FLOAT, HAS_IMAGING BOOLEAN);
CREATE OR REPLACE TABLE REF.PAYERS (PAYER_ID STRING PRIMARY KEY, NAME STRING, SHORT_NAME STRING, REVENUE_SHARE_PCT FLOAT, TARGET_DSO_DAYS INT, PAYER_TYPE STRING);
CREATE OR REPLACE TABLE REF.SPECIALTIES (SPECIALTY_ID STRING PRIMARY KEY, NAME STRING, IS_SURGICAL BOOLEAN);
CREATE OR REPLACE TABLE REF.OR_ROOMS (ROOM_ID STRING PRIMARY KEY, HOSPITAL_ID STRING, NAME STRING, SPECIALTY STRING, TURNOVER_MIN INT, FIRST_CASE_DELAY_MIN INT, UTIL_TODAY_PCT FLOAT, END_TODAY_MIN INT, OVERTIME_TODAY_MIN INT);
CREATE OR REPLACE TABLE REF.OR_CASES_TODAY (ROOM_ID STRING, SEQ INT, PROCEDURE_NAME STRING, SURGEON STRING, ASA INT, PLANNED_START_MIN INT, PLANNED_DURATION_MIN INT, ACTUAL_START_MIN INT, ACTUAL_DURATION_MIN INT, STATUS STRING)
  COMMENT = 'Today''s operating plan at HL Lisboa (minutes from 08:00), as shown on Bloco operatório';
CREATE OR REPLACE TABLE REF.OR_PLAN_TOMORROW (SEQ INT, ROOM STRING, PROCEDURE_NAME STRING, SURGEON STRING, SURGEON_ESTIMATE_MIN INT, MODEL_P50_MIN INT, MODEL_P90_MIN INT, ASA INT, CANCEL_RISK FLOAT);
CREATE OR REPLACE TABLE REF.OR_PREOP (PATIENT_NAME STRING, AGE INT, PROCEDURE_NAME STRING, SLOT STRING, PAYER STRING, CHECKLIST VARIANT, CANCEL_RISK FLOAT, ICU_RISK FLOAT, COMPLICATION_RISK FLOAT, EXPECTED_LOS_DAYS FLOAT);
CREATE OR REPLACE TABLE REF.SURGEONS (SURGEON STRING, SPECIALTY STRING, CASES_30D INT, CANCEL_PCT FLOAT, ON_TIME_PCT FLOAT, COMPLICATION_PCT FLOAT);
CREATE OR REPLACE TABLE REF.OR_TEAM_TODAY (ROLE_NAME STRING, REQUIRED INT, AVAILABLE INT, NOTE STRING);
CREATE OR REPLACE TABLE REF.MODEL_CATALOG (MODEL_ID STRING, NAME STRING, USE_CASE STRING, ALGORITHM STRING, STATUS STRING, METRIC_NAME STRING, METRIC_VALUE STRING, PREDICTIONS_PER_DAY STRING, DESCRIPTION STRING, DETAILS VARIANT, FEATURE_IMPORTANCE VARIANT, LINEAGE VARIANT);
CREATE OR REPLACE TABLE REF.KPI_DICTIONARY (KPI_NAME STRING, DOMAIN STRING, DEFINITION STRING, FORMULA STRING, OWNER STRING, SOURCES VARIANT, SEMANTIC_VIEW STRING, REFRESH STRING, QUALITY_PCT FLOAT, CERTIFIED BOOLEAN);
CREATE OR REPLACE TABLE REF.PLAN_MONTHLY_2026 (MONTH_NUM INT, MONTH_LABEL STRING, ACTUAL_MEUR FLOAT, BUDGET_MEUR FLOAT, FORECAST_MEUR FLOAT);
CREATE OR REPLACE TABLE REF.GROUP_FACTS (FACT_NAME STRING, FACT_VALUE FLOAT);
CREATE OR REPLACE TABLE REF.PATIENT_PROFILES (
  PROFILE_ID STRING PRIMARY KEY, FULL_NAME STRING, SEX STRING, AGE INT, HOSPITAL_ID STRING, MAIN_CONDITION STRING, IS_FEATURED BOOLEAN, META STRING,
  TAGS VARIANT, ALERTS VARIANT, RISKS VARIANT, PROBLEMS VARIANT, MEDICATIONS VARIANT, TIMELINE VARIANT, NEXT_BEST_ACTIONS VARIANT, SUMMARY STRING,
  FINANCE VARIANT, SOCIAL VARIANT, CONSENT VARIANT, INSIGHTS VARIANT, SHAP VARIANT, CARE_GAPS VARIANT
) COMMENT = 'The 240 patient profiles shown in Doente 360°';
CREATE OR REPLACE TABLE REF.EMPLOYEE_PROFILES (
  PROFILE_ID STRING PRIMARY KEY, FULL_NAME STRING, ROLE_NAME STRING, SERVICE STRING, HOSPITAL_ID STRING, IS_FEATURED BOOLEAN, META STRING,
  TAGS VARIANT, RISKS VARIANT, KPIS VARIANT, HOURS VARIANT, SHIFTS VARIANT, TRAINING VARIANT, NEXT_BEST_ACTIONS VARIANT, INSIGHTS VARIANT, PEERS VARIANT, CAREER VARIANT
) COMMENT = 'The 183 employee profiles shown in Colaborador 360°';
CREATE OR REPLACE TABLE REF.SOURCE_SYSTEMS (DOMAIN STRING, SYSTEM_NAME STRING, PRODUCT STRING, DATA_DESCRIPTION STRING, DAILY_VOLUME STRING, INTEGRATION STRING, FRESHNESS STRING, RAW_TABLE STRING)
  COMMENT = 'Catalogue of source systems from the architecture page, with the RAW table each one lands in';
CREATE OR REPLACE TABLE REF.CLINICAL_PROTOCOLS (DOC_ID STRING, TITLE STRING, CATEGORY STRING, SPECIALTY STRING, OWNER STRING, UPDATED_ON DATE, CONTENT STRING)
  COMMENT = 'Clinical and administrative protocols indexed by Cortex Search';
CREATE OR REPLACE TABLE REF.CALENDAR (CAL_DATE DATE PRIMARY KEY, YEAR INT, MONTH INT, MONTH_LABEL STRING, ISO_WEEK INT, WEEKDAY INT, WEEKDAY_LABEL STRING, IS_WEEKEND BOOLEAN, IS_HOLIDAY BOOLEAN, HOLIDAY_NAME STRING);
CREATE OR REPLACE TABLE REF.DISTRICTS (DISTRICT STRING PRIMARY KEY, REGION STRING, LAT FLOAT, LON FLOAT);

-- ============================== RAW: landing tables ==============================
-- Processo clínico (HIS) · ADT as HL7 v2 messages converted to JSON by the integration engine
CREATE OR REPLACE TABLE RAW.HIS_ADT_HL7 (MSG_ID STRING, MSG_TYPE STRING, RECEIVED_AT TIMESTAMP_NTZ, SOURCE STRING, MSG VARIANT)
  COMMENT = 'HL7 v2 ADT (A01 admit / A03 discharge) as JSON · Snowpipe Streaming · < 1 min';
-- Urgência · FHIR R4 Encounter resources
CREATE OR REPLACE TABLE RAW.HIS_ER_ENCOUNTER_FHIR (RESOURCE_ID STRING, RECEIVED_AT TIMESTAMP_NTZ, RESOURCE VARIANT)
  COMMENT = 'FHIR R4 Encounter (emergency) with Manchester triage · Snowpipe Streaming · < 1 min';
-- Consultas (CDC copy of the HIS scheduling tables)
CREATE OR REPLACE TABLE RAW.HIS_APPOINTMENTS (
  APPOINTMENT_ID STRING, UNIT_ID STRING, UNIT_TYPE STRING, SPECIALTY STRING, PATIENT_ID STRING, PAYER_ID STRING,
  BOOKED_AT TIMESTAMP_NTZ, APPOINTMENT_TS TIMESTAMP_NTZ, BOOKING_CHANNEL STRING, IS_TELECONSULT BOOLEAN, IS_FIRST_VISIT BOOLEAN,
  CONFIRMED_IN_APP BOOLEAN, DISTANCE_KM FLOAT, RAIN_FORECAST BOOLEAN, STATUS STRING, _CDC_OP STRING, _CDC_TS TIMESTAMP_NTZ
) COMMENT = 'Outpatient appointments · CDC via Openflow · 15 min';
-- Bloco operatório (surgical log)
CREATE OR REPLACE TABLE RAW.HIS_SURGERY_LOG (
  CASE_ID STRING, HOSPITAL_ID STRING, ROOM_ID STRING, SPECIALTY STRING, PROCEDURE_NAME STRING, SURGEON STRING, PATIENT_ID STRING, PAYER_ID STRING, ASA INT, AGE INT,
  SURGERY_DATE DATE, PLANNED_START TIMESTAMP_NTZ, SURGEON_ESTIMATE_MIN INT, ACTUAL_START TIMESTAMP_NTZ, ACTUAL_DURATION_MIN INT, TURNOVER_MIN INT,
  IS_ROBOTIC BOOLEAN, CANCELLED_SAME_DAY BOOLEAN, CANCEL_REASON STRING, ICU_AFTER BOOLEAN, _CDC_TS TIMESTAMP_NTZ
) COMMENT = 'Surgical log (HL7 SIU / FHIR Procedure) · < 1 min';
-- Laboratório (LIS · Clinidata) results coded in LOINC
CREATE OR REPLACE TABLE RAW.LIS_RESULTS (RESULT_ID STRING, PATIENT_ID STRING, HOSPITAL_ID STRING, LOINC_CODE STRING, TEST_NAME STRING, VALUE_NUM FLOAT, UNIT STRING, COLLECTED_AT TIMESTAMP_NTZ, MSG VARIANT)
  COMMENT = 'Lab results (HL7 ORU) · 5 min';
-- Faturação clínica e convenções (CDC)
CREATE OR REPLACE TABLE RAW.BILLING_INVOICES (
  INVOICE_ID STRING, EPISODE_ID STRING, EPISODE_TYPE STRING, HOSPITAL_ID STRING, PATIENT_ID STRING, PAYER_ID STRING, SPECIALTY STRING,
  SERVICE_DATE DATE, INVOICE_DATE DATE, AMOUNT_EUR NUMBER(12,2), HAS_PRIOR_AUTH BOOLEAN, NEEDS_PRIOR_AUTH BOOLEAN, IS_IMAGING BOOLEAN,
  STATUS STRING, PAID_DATE DATE, _CDC_TS TIMESTAMP_NTZ
) COMMENT = 'Invoices and payer claims · CDC via Openflow · 15 min';
-- Seguradoras: free-text answers to claims (classified with AI_CLASSIFY)
CREATE OR REPLACE TABLE RAW.PAYER_RESPONSES (RESPONSE_ID STRING, INVOICE_ID STRING, PAYER_ID STRING, RECEIVED_AT TIMESTAMP_NTZ, OUTCOME STRING, RESPONSE_TEXT STRING)
  COMMENT = 'Payer responses (API/EDI) · free text, Portuguese';
-- SAP S/4HANA · material stock and consumption by hospital
CREATE OR REPLACE TABLE RAW.SAP_STOCK_DAILY (HOSPITAL_ID STRING, MATERIAL_ID STRING, MATERIAL_NAME STRING, CATEGORY STRING, STOCK_DATE DATE, STOCK_UNITS INT, CONSUMED_UNITS INT, SAFETY_STOCK INT, UNIT_COST_EUR NUMBER(10,2), EXPIRY_DATE DATE)
  COMMENT = 'SAP MM stock snapshot and consumption · Openflow SAP connector · 15 min';
-- SAP SuccessFactors employees (OData JSON) and UKG rosters
CREATE OR REPLACE TABLE RAW.SF_EMPLOYEES (EMPLOYEE_ID STRING, PAYLOAD VARIANT, _LOADED_AT TIMESTAMP_NTZ) COMMENT = 'SuccessFactors employee records (OData) · daily';
CREATE OR REPLACE TABLE RAW.UKG_SHIFTS (SHIFT_ID STRING, EMPLOYEE_ID STRING, HOSPITAL_ID STRING, SHIFT_DATE DATE, SHIFT_TYPE STRING, HOURS FLOAT, IS_OVERTIME BOOLEAN, REST_HOURS_BEFORE FLOAT)
  COMMENT = 'UKG rosters and time · 15 min';
-- Patient master (MPI feed from the HIS)
CREATE OR REPLACE TABLE RAW.HIS_PATIENTS (PATIENT_ID STRING, PROFILE_ID STRING, FULL_NAME STRING, SEX STRING, BIRTH_DATE DATE, DISTRICT STRING, MAIN_PAYER_ID STRING, IS_PRIME BOOLEAN, MYLUZ_USER BOOLEAN, CHARLSON_INDEX INT, CONSENT_RESEARCH BOOLEAN, CONSENT_HEALTH_COMMS BOOLEAN, CREATED_AT TIMESTAMP_NTZ)
  COMMENT = 'Patient master index from the HIS';
-- App MY LUZ events (Kafka)
CREATE OR REPLACE TABLE RAW.MYLUZ_EVENTS (EVENT_ID STRING, PATIENT_ID STRING, EVENT_TS TIMESTAMP_NTZ, EVENT VARIANT) COMMENT = 'MY LUZ app events · Kafka → Snowpipe Streaming';
-- Unstructured: clinical notes and customer feedback
CREATE OR REPLACE TABLE RAW.CLINICAL_NOTES (NOTE_ID STRING, PATIENT_ID STRING, HOSPITAL_ID STRING, EPISODE_ID STRING, NOTE_TYPE STRING, AUTHOR_ROLE STRING, CREATED_AT TIMESTAMP_NTZ, NOTE_TEXT STRING)
  COMMENT = 'Clinical notes (discharge letters, progress notes) · free text, Portuguese';
CREATE OR REPLACE TABLE RAW.CUSTOMER_FEEDBACK (FEEDBACK_ID STRING, PATIENT_ID STRING, HOSPITAL_ID STRING, TOUCHPOINT STRING, CHANNEL STRING, NPS_SCORE INT, CREATED_AT TIMESTAMP_NTZ, COMMENT_TEXT STRING)
  COMMENT = 'NPS surveys (Qualtrics) and complaints · free text';

-- ============================== EXT: external signals (Marketplace) ==============================
CREATE OR REPLACE TABLE EXT.WEATHER_DAILY (DISTRICT STRING, OBS_DATE DATE, TEMP_MIN_C FLOAT, TEMP_MAX_C FLOAT, PRECIP_MM FLOAT, SOURCE STRING DEFAULT 'IPMA') COMMENT = 'IPMA daily weather by district';
CREATE OR REPLACE TABLE EXT.WASTEWATER_WEEKLY (REGION STRING, WEEK_START DATE, RESPIRATORY_VIRUS_INDEX FLOAT, SOURCE STRING DEFAULT 'INSA') COMMENT = 'INSA wastewater surveillance (respiratory viruses)';
CREATE OR REPLACE TABLE EXT.FLU_INCIDENCE_WEEKLY (REGION STRING, WEEK_START DATE, ILI_PER_100K FLOAT, SOURCE STRING DEFAULT 'INSA/DGS') COMMENT = 'Influenza-like illness incidence';
CREATE OR REPLACE TABLE EXT.AIR_QUALITY_DAILY (DISTRICT STRING, OBS_DATE DATE, PM25 FLOAT, SOURCE STRING DEFAULT 'APA QualAr');
CREATE OR REPLACE TABLE EXT.SEARCH_TRENDS_WEEKLY (TERM STRING, REGION STRING, WEEK_START DATE, INTEREST_INDEX FLOAT, SOURCE STRING DEFAULT 'Google Trends');
